"""Insight and progress-related database models."""

from datetime import datetime
from sqlalchemy import Boolean, Column, String, Text, DateTime, Float, JSON, ForeignKey, Uuid

from app.models.base import BaseModel


class Insight(BaseModel):
    """Health insight generated by AI."""
    
    __tablename__ = "insights"

    user_id = Column(Uuid(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    insight_type = Column(String(50), nullable=False)  # posture, flexibility, balance
    severity = Column(String(20))  # low, medium, high
    title = Column(String(255))
    description = Column(Text)
    action_items = Column(JSON)
    related_metrics = Column(JSON)
    seen = Column(Boolean, default=False, nullable=False)
    acknowledged = Column(Boolean, default=False, nullable=False)
    expires_at = Column(DateTime)


class ProgressMetric(BaseModel):
    """Progress metrics for a user."""
    
    __tablename__ = "progress_metrics"

    user_id = Column(Uuid(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    metric_type = Column(String(50), nullable=False)  # yoga_score, posture_score, session_count
    value = Column(Float, nullable=False)
    unit = Column(String(20))
    recorded_at = Column(DateTime, nullable=False, index=True)
    metric_metadata = Column("metadata", JSON, default=dict)
